import { Entity } from "../../Engine/Entity";



export class Bullet extends Entity {
    readonly kind = 'bullet';

    /** 方向单位向量的 x 分量 */
    public dirX = 0;
    /** 方向单位向量的 y 分量 */
    public dirY = 1;

    /** 速度，单位像素/秒 */
    public speed = 0;

    /** 命中后扣血量 */
    public damage = 0;

    /** 是否玩家阵营子弹。默认 false（敌人子弹），玩家子弹显式设 true */
    public isPlayerBullet = false;
}